const input = $input.item.json;

// Extract fields
function extract(obj, keys) {
  for (const key of keys) {
    if (obj[key]) return String(obj[key]).trim();
  }
  return '';
}

const data = {
  email: extract(input, ['Email_Address', 'email', 'Email']),
  fullName: extract(input, ['Full_Name', 'fullName', 'name']),
  phone: extract(input, ['Phone_Number', 'phone']),
  company: extract(input, ['Company_Name', 'company']),
  address: extract(input, ['Address', 'address']),
  clientSummary: extract(input, ['Client_Summary__AI_', 'clientSummary', 'summary']),
  clientType: extract(input, ['Client_Type', 'clientType', 'type']),
  account: extract(input, ['Account', 'account']),
  photoUrl: extract(input, ['Photo_URL', 'photoUrl'])
};

// Validation
if (!data.email || !data.fullName) {
  throw new Error('Email and Full Name are required');
}

return { json: { action: 'upsert', data: data } };

